varying vec2 vUv;

void main() {
    vUv = uv;
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}

uniform float progress;
uniform vec3 color;
varying vec2 vUv;

void main() {
    float pulse = 0.65 + 0.35 * sin((progress + vUv.y * 0.25) * 6.2831853);
    gl_FragColor = vec4(color * pulse, 1.0);
}

// texture1 is the wired IMAGE. The colour multiplies it, so a dark photograph is lifted.
return new THREE.MeshStandardMaterial({
    map: texture1,
    color: "#b9d4ff",
    roughness: 0.4,
    metalness: 0.2,
    emissive: "#101820",
});

// Built once per load and handed out by the three Three Import nodes.
const gold = new THREE.MeshStandardMaterial({
    color: "#d8b24a", metalness: 0.9, roughness: 0.18
});
const knot = new THREE.TorusKnotGeometry(0.55, 0.18, 128, 24);
const marker = new THREE.Mesh(
    new THREE.OctahedronGeometry(0.35),
    new THREE.MeshStandardMaterial({ color: "#8fff9f", emissive: "#1b5c26" })
);
marker.position.set(0, 4.4, 0);
return { gold, knot, marker };

const mesh = new THREE.Mesh(geometry1, material1);
mesh.castShadow = true;
mesh.receiveShadow = true;
mesh.position.set(-1.7, 2.4, -2.4);
return mesh;

// ctx carries the captured window, so this loops with the turn beside it.
const span = Number(ctx.duration) || 1;
const along = (time - (Number(ctx.timeOrigin) || 0)) / span;
object.position.y = Math.sin(along * Math.PI * 2) * 0.35;
